## Code Example
```javascript
async function boundaryDecision(user, request) {
  const ctx = await getTenantContext(user.tenantId); // from Azure AD
  const policy = await queryKB("policy", ctx);
  const subset = applyMinimization(request.data, policy, ctx);
  // force RBAC at data layer
  if (!hasAccess(user, subset)) throw new Error("Access denied");
  const rationale = `Selected ${subset.length} records for tenant ${ctx.name} per policy.`;
  await logAudit({user, request, subset, ctx});
  return { subset, rationale };
}
```

